681	  });
682	  els.roles?.addEventListener("click", (event) => {
683	    const target = (event.target as HTMLElement).closest<HTMLButtonElement>("[data-role]");
684	    if (!target?.dataset.role) return;
685	    interveneRole = target.dataset.role as PlayerInterventionInput["targetRole"];
686	    els.roles!.querySelectorAll<HTMLButtonElement>("[data-role]").forEach((btn) => btn.classList.toggle("is-selected", btn === target));
687	  });
