898	      <p class="debrief-target">${debrief.met ? "LOCAL TARGET MET" : "LOCAL TARGET MISSED"}</p>
899	      <p class="debrief-grade"><strong>${escapeHtml(debrief.grade)}</strong> ${escapeHtml(debrief.headline)}</p>
900	      ${targets ? `<p class="debrief-criteria">Local target checks</p><ul class="debrief-checks">${targets}</ul>` : ""}
901	      <p class="debrief-criteria">Raw operational facts</p>
902	      <div class="debrief-stats">${lines}</div>
903	      <p class="debrief-caveat">No wait figure: the engine derives only a whole-shift clock reading, not an arrival-to-seat measurement.</p>
904	      <ul class="debrief-lessons">${lessons}</ul>
905	    </div>`;
