export const PREVIEW_RESIZE_MESSAGE = "gamepigeon:preview-resize";

/**
 * The overlay's four window sizes, in logical pixels. The native frame and the
 * browser preview (overlay/preview.html) use the same numbers, so a layout
 * fixed in the preview is fixed in the app — see "Window sizes" in the README.
 */
export interface OverlaySize {
  readonly width: number;
  readonly height: number;
}

/** Boot size, and what the expand control returns to. */
export const COMPACT_SIZE: OverlaySize = { width: 600, height: 850 };
/** The expand control's other half: room for the arena's side panels. */
export const EXPANDED_SIZE: OverlaySize = { width: 830, height: 900 };
/** Minimized: only the draggable pill is painted, the rest of the window is transparent. */
export const PILL_SIZE: OverlaySize = { width: 144, height: 48 };
/**
 * The floor a restored window may not drop below. The pill is far smaller than
 * this, so collapsing has to lower the minimum first and raise it again on the
 * way back out — see `applyOverlaySize`.
 */
export const MIN_SIZE: OverlaySize = { width: 500, height: 700 };

/**
 * Resize the overlay window, keeping the enforced minimum consistent with the
 * size being applied. Order matters in both directions: a minimum above the
 * target silently clamps the resize, so shrinking lowers the minimum first and
 * growing raises it afterwards.
 */
export async function applyOverlaySize(
  windowHandle: OverlayWindow,
  size: OverlaySize,
  minimum: OverlaySize = MIN_SIZE,
): Promise<void> {
  const shrinking = size.width < minimum.width || size.height < minimum.height;
  const floor = shrinking ? size : minimum;
  if (shrinking) await windowHandle.setMinSize(overlayLogicalSize(floor.width, floor.height));
  await windowHandle.setSize(overlayLogicalSize(size.width, size.height));
  if (!shrinking) await windowHandle.setMinSize(overlayLogicalSize(floor.width, floor.height));
}

