/**
 * The pause dialog, as pure state.
 *
 * A pause arrives from two directions — the harness `Stop` hook, when the agent
 * wants the human back, and the player's own `Esc`/hide — and the answer to
 * "does anything happen?" depends only on what is on screen. Keeping that
 * decision here means the DOM wiring in app.ts stays a thin translation of it.
 */

/** Who asked for the pause. */
export type PauseSource = "agent" | "player";

/** What a key press inside the dialog means. */
export type PauseCommand = "back-to-coding" | "continue" | "menu" | "how-to-play";

export interface PauseRequest {
  /** Is a run on screen? There is nothing to pause on the menu. */
  inRun: boolean;
  /** A finished shift already has its own end card; don't cover it. */
  over: boolean;
  source: PauseSource;
}

export interface PausePrompt {
  show: boolean;
  title: string;
}

/**
 * The agent's pause names why the overlay just took the screen; the player's
 * pause does not need explaining to the person who asked for it.
 */
export function pausePrompt(request: PauseRequest): PausePrompt {
  return {
    show: request.inRun && !request.over,
    title: request.source === "agent" ? "Your agent needs you" : "Paused",
  };
}

/**
 * The dialog's keyboard map. `Enter` and `Esc` both go back to the coding
 * prompt — that is the shortcut the `Stop` hook advertises, and the one a
 * player who never wanted the overlay reaches for.
 */
export function pauseCommandForKey(key: string): PauseCommand | null {
  switch (key) {
    case "Enter":
    case "Escape":
      return "back-to-coding";
    case "c":
    case "C":
    case " ":
      return "continue";
    case "m":
    case "M":
      return "menu";
    case "?":
    case "h":
    case "H":
      return "how-to-play";
    default:
      return null;
  }
}

/** True for the commands that hand the shift back to the player. */
export function resumesPlay(command: PauseCommand): boolean {
  return command === "continue";
}

