84	function browserKey(event: KeyboardEvent): Key | null {
85	  switch (event.key) {
86	    case "ArrowUp": return "up";
87	    case "ArrowDown": return "down";
88	    case "ArrowLeft": return "left";
89	    case "ArrowRight": return "right";
90	    case "Enter": return "enter";
91	    case "Backspace": return "backspace";
92	  }
93	  if (event.key.length !== 1) return null;
94	  const lower = event.key.toLowerCase();
95	  if (lower === "w") return "up";
96	  if (lower === "s") return "down";
97	  if (lower === "a") return "left";
98	  if (lower === "d") return "right";
99	  if (lower === "q") return "quit";
100	  return { char: event.key };
101	}
