192	/**
193	 * Hands full chunks to the local recording store while the episode is still
194	 * running, so a long game is not stuck in the browser journal until it ends.
195	 * Sealed chunks are byte-stable, so the store treats the eventual final
196	 * submit of the same chunk ids as a no-op.
197	 */
198	const FLUSH_INTERVAL_MS = 5_000;
199	let flushTimer: number | undefined;
200	
201	/**
202	 * Sealing replays the whole journal, so coalesce bursts of input (a gravity
203	 * tick arrives several times a second) onto a slow timer.
204	 */
205	function scheduleTraceFlush(trace: StoredOverlayTrace): void {
206	  if (flushTimer !== undefined) return;
207	  flushTimer = window.setTimeout(() => {
208	    flushTimer = undefined;
209	    if (activeTrace === trace) flushSealedTrace(trace);
210	  }, FLUSH_INTERVAL_MS);
211	}
212	
213	function cancelTraceFlush(): void {
214	  if (flushTimer !== undefined) window.clearTimeout(flushTimer);
215	  flushTimer = undefined;
216	}
