218	function flushSealedTrace(trace: StoredOverlayTrace): void {
219	  try {
220	    const sealed = buildSealedOverlayTraceChunks(trace, appVersion());
221	    const alreadyFlushed = trace.flushedChunks ?? 0;
222	    const chunks = sealed.slice(alreadyFlushed);
223	    if (chunks.length === 0) return;
224	    trace.flushedChunks = sealed.length;
225	    persistTrace(trace);
226	    void invoke("queue_recording_chunks", { chunks, result: null }).catch(() => {
227	      // Leave them for the next flush or the end-of-episode submit.
228	      trace.flushedChunks = alreadyFlushed;
229	    });
230	  } catch {
231	    // Recording must never interrupt gameplay.
232	  }
233	}
