235	function submitTrace(
236	  trace: StoredOverlayTrace,
237	  reason: EpisodeEndReason,
238	  completedScore?: number,
239	): void {
240	  if (!settings.recordingWhilePlaying) return;
241	  try {
242	    trace.endReason ??= reason;
243	    trace.endedAtMs ??= Date.now();
244	    trace.completedScore ??= completedScore;
245	    persistTrace(trace);
246	    const chunks = buildOverlayTraceChunks(
247	      trace,
248	      trace.endReason,
249	      appVersion(),
250	      trace.endedAtMs,
251	    );
252	    void invoke("queue_recording_chunks", {
253	      chunks,
254	      result: buildOverlayGameResult(trace),
255	    }).then(() => {
256	      localStorage.removeItem(`${TRACE_KEY_PREFIX}${trace.gameId}`);
257	    }).catch(() => {
258	      // Keep the compact seed/action journal for the next launch.
259	    });
260	  } catch {
261	    // Keep the journal if replay or serialization fails.
262	  }
263	}
