265	function recoverTraces(): void {
266	  const pending: StoredOverlayTrace[] = [];
267	  for (let index = 0; index < localStorage.length; index++) {
268	    const key = localStorage.key(index);
269	    if (!key?.startsWith(TRACE_KEY_PREFIX)) continue;
270	    try {
271	      pending.push(JSON.parse(localStorage.getItem(key)!) as StoredOverlayTrace);
272	    } catch {
273	      // Preserve malformed recovery data for manual inspection.
274	    }
275	  }
276	  for (const trace of pending) submitTrace(trace, trace.endReason ?? "client_closed");
277	}
