541	  const message = workerBudgetMessage(state, workerModelLabel());
542	  if (!message) {
543	    setWorkerMode();
544	    return;
545	  }
546	  setWorkerMode(message, "waiting");
547	  workerBudgetTimer = setTimeout(() => setWorkerBudget(WORKER_BUDGET_CLEAR), workerBudgetHoldMs(state));
548	}
