584	interface WorkerModelResponse {
585	  text: string;
586	  queueMs: number;
587	  providerMs: number;
588	  inputTokens?: number;
589	  outputTokens?: number;
590	  cachedInputTokens?: number;
591	  finishReason?: string;
592	}
