594	/** Absent provider fields (no usage on this response) stay absent, not zero. */
595	function workerModelMetrics(response: WorkerModelResponse): ModelCallMetrics {
596	  return {
597	    queueMs: response.queueMs,
598	    providerMs: response.providerMs,
599	    ...(response.inputTokens !== undefined ? { inputTokens: response.inputTokens } : {}),
600	    ...(response.outputTokens !== undefined ? { outputTokens: response.outputTokens } : {}),
601	    ...(response.cachedInputTokens !== undefined ? { cachedInputTokens: response.cachedInputTokens } : {}),
602	    ...(response.finishReason !== undefined ? { finishReason: response.finishReason } : {}),
603	  };
604	}
