606	function attachWorkerOrchestrator(activeGame: PlayableGame): void {
607	  if (!workerModel || activeGame.name !== "restaurant-arena") return;
608	  workerActivity.length = 0;
609	  const arena = activeGame as unknown as RestaurantGame;
610	  const client = new WorkerModelClient({
611	    retries: 0,
612	    // The Rust transport bounds the provider call and starts that bound after
613	    // the request budget admits it, so queue time is not charged to the
614	    // worker. A timer here would start while the request is still in line and
615	    // abort a crew that is only waiting its turn.
616	    timeoutMs: null,
617	    complete: async (request: ModelRequest, signal: AbortSignal) => {
618	      const role = request.observation.role;
619	      const startedAt = performance.now();
620	      setWorkerStatus(role, "thinking");
621	      // A request already queued behind the account's share is not pending on
622	      // the model; the budget banner is the more specific thing to say. The
623	      // activity feed still logs the request either way -- it is a log of what
624	      // happened, not a description of the current state.
625	      if (shouldReportFallback(workerBudget)) setWorkerMode(`Pending · ${workerModelLabel()} · ${role}`, "pending");
626	      addWorkerActivity(`${role}: requested live action`);
627	      const requestId = crypto.randomUUID();
628	      const cancel = () => void invoke("cancel_worker_model", { requestId });
629	      signal.addEventListener("abort", cancel, { once: true });
630	      try {
631	        const response = await invoke<WorkerModelResponse>("complete_worker_model", {
632	          requestId,
633	          request: { systemPrompt: request.systemPrompt, turnPrompt: request.turnPrompt },
634	        });
635	        if (signal.aborted) throw new Error("model request canceled");
636	        setWorkerStatus(role, "acting");
637	        addWorkerActivity(`${role}: response received in ${Math.round(performance.now() - startedAt)}ms`);
638	        return { text: response.text, metrics: workerModelMetrics(response) };
639	      } finally {
640	        signal.removeEventListener("abort", cancel);
641	      }
642	    },
643	  });
644	  let orchestrator: WorkerOrchestrator;
645	  orchestrator = new WorkerOrchestrator(arena, {
646	    client,
647	    model: workerModel,
648	    tickIntervalMs: () => arena.tickMs() || 1_000,
649	    onError: (turn) => {
650	      if (workerOrchestrator !== orchestrator) return;
651	      setWorkerStatus(turn.role, "error");
652	      addWorkerActivity(`${turn.role}: fallback — ${turn.error ?? "invalid action"}`);
653	      // A shift held back by the shared account is waiting, not broken (#281).
654	      // Only the banner is suppressed; the feed above still records the turn.
655	      if (!shouldReportFallback(workerBudget)) return;
656	      setWorkerMode(`Fallback · ${workerModelLabel()} · ${turn.role}: ${turn.error ?? "invalid action"}`, "error");
657	    },
658	    onTick: (report: OrchestratorTick) => {
659	      if (workerOrchestrator !== orchestrator || game !== activeGame) return;
660	      for (const turn of report.turns) {
661	        if (turn.status === "accepted") {
662	          setWorkerStatus(turn.role, "acting");
663	          addWorkerActivity(`${turn.role}: applied ${turn.action?.tool ?? "action"}`);
664	        }
665	        else if (turn.status === "fallback" || turn.status === "rejected") setWorkerStatus(turn.role, "error");
666	      }
667	      // Turns landing again is proof the account is answering, whatever the
668	      // last throttle said was left on its countdown.
669	      if (report.turns.every((turn) => turn.status === "accepted")) setWorkerBudget(WORKER_BUDGET_CLEAR);
670	      drawGame();
671	    },
672	  });
673	  workerOrchestrator = orchestrator;
674	}
