676	/** Every control funnels through here — the panel's only write path. */
677	function submitIntervention(input: PlayerInterventionInput): void {
678	  if (!game) return;
679	  const withIntervene = game as PlayableGame & {
680	    submitPlayerIntervention?: (i: PlayerInterventionInput) => { accepted: boolean; error?: { message: string } };
681	  };
682	  if (!withIntervene.submitPlayerIntervention) return;
683	  workerOrchestrator?.pause();
684	  const result = withIntervene.submitPlayerIntervention(input);
685	  if (result.accepted) {
686	    setInterveneStatus("Sent.");
687	  } else {
688	    setInterveneStatus(result.error?.message ?? "Could not send that.", "error");
689	  }
690	  // A rejected stale/invalid intervention must not strand live workers in the
691	  // paused state either; drawGame() re-enters the selected scheduler.
692	  drawGame();
693	}
