758	/** Refill the ticket list and the approve/deny section from the live view — never the message box, so an in-progress draft survives a tick. */
759	function refreshInterventionPanel(activeGame: PlayableGame): void {
760	  if (activeGame.name !== "restaurant-arena") return;
761	  const els = interveneEls();
762	  if (!els.panel) return;
763	  const view = arenaView(activeGame);
764	
765	  const live = (view.orders ?? []).filter((order) => order.status !== "served" && order.status !== "cancelled");
766	  if (els.tickets) {
767	    els.tickets.innerHTML = live.length
768	      ? live
769	          .map((order) => {
770	            const label = (order.tableId ?? order.id).replace("table-", "T");
771	            const alreadyHigh = order.priority === "high";
772	            return `<button type="button" class="arena-intervene-ticket" data-order-id="${order.id}"${alreadyHigh ? " data-already-high" : ""}>${label} · ${order.items.join("+") || "—"}${alreadyHigh ? " (high)" : ""}</button>`;
