808	            (option) =>
809	              `<button type="button" class="arena-intervene-approve-option" data-tone="${option.tone}" data-decision-id="${decision.id}" data-option-id="${option.id}" data-speaker-role="${decision.speakerRole}">${option.label}</button>`,
810	          )
