891	/** The service report: what the shift scored, and what to fix next run. */
892	function getArenaDebriefHtml(): string {
893	  if (!game || game.name !== "restaurant-arena") return "";
894	  const view = arenaView(game) as unknown as { debrief?: ArenaDebrief };
895	  const debrief = view.debrief;
896	  if (!debrief) return "";
897	  // Whatever the target checks already reported is dropped here: showing
898	  // "Takings $96" twice, once as a verdict and once as a stat, made the card
899	  // longer without making it say more.
900	  const checked = new Set((debrief.targets ?? []).map((target) => target.label.toLowerCase()));
901	  const lines = debrief.lines
902	    .filter((line) => !checked.has(line.label.toLowerCase()))
903	    .map(
904	      (line) =>
905	        `<span class="debrief-stat${line.good ? " is-good" : ""}"><small>${escapeHtml(line.label)}</small><strong>${escapeHtml(line.value)}</strong></span>`,
906	    )
907	    .join("");
908	  const lessons = debrief.lessons.map((lesson) => `<li>${escapeHtml(lesson)}</li>`).join("");
909	  // The verdict names which condition decided it. `lines` below are a
910	  // read-at-a-glance summary of the shift on their own thresholds, which are
911	  // not tonight's pass bar — keeping the two apart is what stops a green
912	  // "Walkouts 2" from sitting under a MISSED verdict it actually caused.
913	  const targets = (debrief.targets ?? [])
914	    .map(
915	      (target) =>
916	        `<li class="debrief-check${target.met ? " is-met" : ""}">` +
917	        `<span class="check-mark">${target.met ? "met" : "miss"}</span>` +
918	        `<span class="check-label">${escapeHtml(target.label)}</span>` +
919	        `<span class="check-value">${escapeHtml(target.value)}</span>` +
920	        `<span class="check-req">needs ${escapeHtml(target.requirement)}</span>` +
921	        `</li>`,
922	    )
923	    .join("");
924	  return `
925	    <div class="arena-debrief"${debrief.met ? ' data-met="yes"' : ""}>
926	      <p class="debrief-scope">Local gameplay summary · not an official evaluation</p>
927	      <p class="debrief-target">${debrief.met ? "LOCAL TARGET MET" : "LOCAL TARGET MISSED"}</p>
928	      <p class="debrief-grade"><strong>${escapeHtml(debrief.grade)}</strong> ${escapeHtml(debrief.headline)}</p>
929	      ${targets ? `<p class="debrief-criteria">Local target checks</p><ul class="debrief-checks">${targets}</ul>` : ""}
930	      <p class="debrief-criteria">Raw operational facts</p>
931	      <div class="debrief-stats">${lines}</div>
932	      <p class="debrief-caveat">No wait figure: the engine derives only a whole-shift clock reading, not an arrival-to-seat measurement.</p>
933	      <ul class="debrief-lessons">${lessons}</ul>
934	    </div>`;
