937	/**
938	 * The evidence receipt: what the shift actually recorded, counted off the
939	 * run's own journal — the same events `Export Trace` writes out as
940	 * restaurant-arena-trace/v3.
941	 *
942	 * Split by who authored each event, because that split is the whole point of
943	 * the export: what the house did on its own (`system`) has to stay separable
944	 * from what the manager handed over (`player`) and what the workers did with
945	 * it. Every number here is counted, never estimated, and nothing is
946	 * attributed to a model that did not stamp the event itself.
947	 */
948	function getArenaEvidenceHtml(): string {
949	  if (!game || game.name !== "restaurant-arena") return "";
950	  const journal = game as unknown as { getRecordedEvents?: () => { actorId?: string; model?: unknown; toolResult?: { ok?: boolean } | null }[] };
951	  if (typeof journal.getRecordedEvents !== "function") return "";
952	  let events: { actorId?: string; model?: unknown; toolResult?: { ok?: boolean } | null }[];
953	  try {
954	    events = journal.getRecordedEvents();
955	  } catch (err) {
956	    console.error("Failed to read the arena event journal:", err);
957	    return "";
958	  }
959	  const system = events.filter((event) => event.actorId === "system").length;
960	  const manager = events.filter((event) => event.actorId === "player").length;
961	  const worker = events.length - system - manager;
962	  const rejected = events.filter((event) => event.toolResult?.ok === false).length;
963	  const modelStamped = events.filter((event) => event.model !== undefined && event.model !== null).length;
964	  // Only the authorship split gets tiles — that split is what the export is
965	  // for. The rest is one line, because a six-tile grid made a footnote look
966	  // like a scoreboard.
967	  const rows: [string, string][] = [
968	    ["System", `${system}`],
969	    ["Your handover", `${manager}`],
970	    ["Worker turns", `${worker}`],
971	  ];
972	  return `
973	    <div class="arena-evidence">
974	      <p class="debrief-criteria">${events.length} recorded events · exported by <code>Export Trace</code></p>
975	      <div class="evidence-stats">${rows
976	        .map(([label, value]) => `<span class="evidence-stat"><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong></span>`)
977	        .join("")}</div>
978	      <p class="debrief-caveat">${rejected} rejected call${rejected === 1 ? "" : "s"} · ${modelStamped} stamped by a model. Counted from this run&rsquo;s journal, never inferred.</p>
979	    </div>`;
980	}
