1011	/** Export the raw restaurant-arena-trace-v3 JSON or JSONL file. */
1012	function exportCurrentTrace(format: "json" | "jsonl" = "json"): void {
1013	  if (!game || game.name !== "restaurant-arena") return;
1014	  try {
1015	    // A shift played in the overlay is live gameplay by definition; synthetic
1016	    // and benchmark traces are produced by scripts/export-arena-trace.ts.
1017	    const trace = captureArenaTrace(game as unknown as RestaurantGame, {
1018	      runKind: "live",
1019	      ...(sessionReceiptId ? { sessionId: sessionReceiptId } : {}),
1020	    });
1021	    const content = format === "jsonl" ? exportTraceJsonl(trace) : exportTraceJson(trace);
1022	    // Named by session, not episode: `episodeId` is the scenario, so every
1023	    // run of the same seed used to download over the last one (#281).
1024	    const filename = `restaurant-arena-trace-${trace.sessionId ?? trace.episodeId}.${format === "jsonl" ? "jsonl" : "json"}`;
