            if let Some(window) = app.get_webview_window("main") {
                let _ = window.eval("window.dispatchEvent(new Event('gamepigeon:pause'))");
                let _ = window.show();
                let _ = window.set_focus();
            }
        }
        OverlayAction::Hide => {
            if let Some(window) = app.get_webview_window("main") {
                let _ = window.hide();
