content.content:
      Browser preview of the Tui overlay (same compact/expanded sizes as Tauri:
      600×850 compact). Titlebar <strong>↗</strong> toggles the frame. Deep-link with
      <code>?game=restaurant-arena</code>.
    </p>
    <div class="stage" id="stage" aria-label="Overlay preview frame">
      <iframe id="overlay" title="Tui overlay"></iframe>
    </div>
    <p class="meta" id="size-label">600 × 850</p>
    <script>
      const COMPACT = { width: 600, height: 850 };
      const stage = document.getElementById("stage");
      const frame = document.getElementById("overlay");
      const label = document.getElementById("size-label");
      let fillStage = false;

      function applySize(width, height) {
        if (fillStage) return;
        stage.style.setProperty("--preview-width", width + "px");
        stage.style.setProperty("--preview-height", height + "px");
        label.textContent = width + " × " + height;
      }

      const params = new URLSearchParams(location.search);
      if (params.get("scene") === "restaurant-arena") {
        document.querySelector(".hint").innerHTML = "Restaurant Arena scene · resize the browser to test its responsive floor plan.";
        stage.classList.add("scene-preview");
        frame.srcdoc = `<!doctype html><html><head><style>*{box-sizing:border-box}html,body,#restaurant-arena{margin:0;width:100%;height:100%;overflow:hidden;background:#2b2118}</style></head><body><div id="restaurant-arena"></div><script type="module" src="/restaurant-arena-preview.js"><\/script></body></html>`;
        const applySceneSize = () => {
          const width = Math.max(320, Math.min(520, innerWidth - 32));
          applySize(width, Math.max(200, Math.round(width * 300 / 520)));
        };
        applySceneSize();
        window.addEventListener("resize", applySceneSize);
      } else {
      const appParams = new URLSearchParams();
      if (params.get("game")) appParams.set("game", params.get("game"));
      if (params.get("variation")) appParams.set("variation", params.get("variation"));
      if (params.get("scores")) appParams.set("scores", params.get("scores"));
      if (params.get("update")) appParams.set("update", params.get("update"));
      const query = appParams.toString();
      frame.src = "/index.html" + (query ? "?" + query : "");

      applySize(COMPACT.width, COMPACT.height);
      }

      window.addEventListener("message", (event) => {
        const data = event.data;
        if (!data || data.type !== "gamepigeon:preview-resize") return;
        const width = Number(data.width);
        const height = Number(data.height);
        if (!Number.isFinite(width) || !Number.isFinite(height)) return;
        applySize(width, height);
      });
    </script>
  </body>
</html>

