// ── Window chrome ─────────────────────────────────────────────────────
//
// Four sizes, one rule each (README, "Window sizes"): compact on boot, the
// expand control swaps compact and expanded, Esc/`q`/the hide button collapse
// to the pill, and clicking the pill comes back to the compact floor. Only
// `applyOverlaySize` talks to the window, because the minimum size has to move
// in step with the target or the shrink to a 144×48 pill is silently clamped.

/** Anything shorter than this is a click on the pill, not a drag of it. */
const PILL_DRAG_THRESHOLD_PX = 4;

function boardSize(): OverlaySize {
  return expanded ? EXPANDED_SIZE : COMPACT_SIZE;
}

/** Collapsed mode is a body attribute; the stylesheet hides everything but the pill. */
function setPillMode(on: boolean): void {
  if (on) document.body.dataset.mode = "pill";
  else delete document.body.dataset.mode;
}

function syncResizeControl(): void {
  const button = document.querySelector<HTMLButtonElement>("#resize");
  if (!button) return;
  setText(button, expanded ? "↙" : "↗");
  button.setAttribute("aria-label", expanded ? "Compact overlay" : "Expand overlay");
}

function toggleExpanded(): void {
  expanded = !expanded;
  syncResizeControl();
  void applyOverlaySize(windowHandle, boardSize());
}

function minimizeToPill(): void {
  // Nobody is watching the floor from behind the pill, so the shift is held
  // rather than left to burn down unattended; the pause dialog waiting under
  // the pill is what hands it back.
  requestPause("player");
  if (minimized) return;
  minimized = true;
  setPillMode(true);
  void applyOverlaySize(windowHandle, PILL_SIZE);
}

function restoreFromPill(): void {
  if (!minimized) return;
  minimized = false;
  setPillMode(false);
  // Restoring always comes back to the compact floor, never below the 500×700
  // minimum the pill had to drop under.
  expanded = false;
  syncResizeControl();
  void applyOverlaySize(windowHandle, COMPACT_SIZE).then(() => windowHandle.center());
}

function bindPill(): void {
  const pill = document.querySelector<HTMLButtonElement>("#pill");
  if (!pill) return;
  let origin: { x: number; y: number } | undefined;
  let dragged = false;
  pill.addEventListener("pointerdown", (event) => {
    origin = { x: event.clientX, y: event.clientY };
    dragged = false;
  });
  pill.addEventListener("pointermove", (event) => {
    if (!origin || dragged) return;
    if (Math.abs(event.clientX - origin.x) < PILL_DRAG_THRESHOLD_PX
