// ── The clock ─────────────────────────────────────────────────────────
//
// `tickMs()` is the engine's answer to "should time pass right now?" — it
// returns 0 whenever the shift is not running, including while a decision card
// holds the floor. Every path that changes the game re-reads it through
// `syncScheduler`, so a stopped clock is always a stopped crew.

function stopTick(): void {
  if (tickTimer !== undefined) window.clearTimeout(tickTimer);
  tickTimer = undefined;
}

function syncScheduler(): void {
  stopTick();
  if (!game || paused || replaying || gameEnded || game.isOver()) {
    workerOrchestrator?.pause();
    return;
  }
  const interval = game.tickMs?.() ?? 0;
  if (interval <= 0) {
    workerOrchestrator?.pause();
    return;
  }
  // A live crew advances the clock itself, one tick per completed round of
  // worker turns; two schedulers on the same game would double-tick it.
  if (workerOrchestrator) {
    workerOrchestrator.start();
    return;
  }
  tickTimer = window.setTimeout(advanceClock, interval);
}

function advanceClock(): void {
  tickTimer = undefined;
  if (!game || paused || replaying || gameEnded || game.isOver()) return;
  stepGame("tick", "environment");
  drawGame();
}

