/** A fresh run gets a fresh seed; only a resume or a recovery reuses a stored one. */
function randomSeed(): number {
  return Math.floor(Math.random() * 2 ** 31);
}

/** Saves are per-account, so the preview's anonymous player owns the empty id. */
