function launchRun(target: GameEntry, variationId: string, seed: number, resumed?: ResumedRun): void {
  if (!target.create) return;
  teardownRun();
  closeDialogs();

  entry = target;
  runVariationId = variationId;
  const variationIndex = target.variations.findIndex((variation) => variation.id === variationId);
  variationCursor = variationIndex === -1 ? 0 : variationIndex;
  const menuIndex = MENU_GAMES.findIndex((item) => item.id === target.id);
  if (menuIndex !== -1) cursor = menuIndex;

  if (resumed) {
    game = resumed.game;
  } else {
    game = target.create(variationId);
    game.reset(seed);
  }
  paused = false;
  gameEnded = false;
  replaying = false;
  minimized = false;
  setPillMode(false);
  gameStartedAt = Date.now();
  actionsTaken = resumed?.actions.length ?? 0;
  screen = "game";

  activeTrace = createOverlayTrace(target, variationId, seed);
  // A resumed run carries its replayed history into the new journal, so the
  // recorded episode describes the whole shift and not just tonight's half.
  for (const action of resumed?.actions ?? []) appendOverlayAction(activeTrace, action, "human");
  // The session id a tester reads off the end card is this run's game id (#281).
  sessionReceiptId = gameSessionId = activeTrace.gameId;

  saveRecord = resumed?.saved ?? newSavedGame(target, variationId, seed, ownerId());
  savedGame = saveRecord;
  saveGame(saveRecord);

  captureOverlayEvent("game.started", { game_type: target.id, variation_id: variationId }, gameSessionId);
  renderGameScreen();
  attachWorkerOrchestrator(game);
  syncScheduler();
}

/** Everything that outlives a single run has to be let go of here. */
function teardownRun(): void {
  stopTick();
  cancelTraceFlush();
  stopWorkerOrchestrator();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  game = undefined;
  saveRecord = undefined;
  paused = false;
  activeTrace = undefined;
}

function startVariation(index: number): void {
  if (!entry) return;
  const variation = entry.variations[index];
  if (!variation) return;
  variationCursor = index;
  launchRun(entry, variation.id, randomSeed());
}

/** The menu's Resume button and the `resumeLastGame` preference share this path. */
function resumeSavedGame(): void {
  const saved = savedGame;
  if (!saved) return;
  const target = findGame(saved.gameId);
  const restored = target ? restoreGame(target, saved) : null;
  if (!target || !restored) {
    // A record this build can no longer rebuild (older rules, renamed action)
    // is dropped rather than left offering a Resume that does nothing.
    savedGame = undefined;
    clearSavedGame();
    if (screen === "menu") drawMenu();
    return;
  }
  launchRun(target, saved.variationId, saved.seed, { ...restored, saved });
}

