function restartRun(): void {
  if (!entry || !game) return;
  const target = entry;
  const variationId = runVariationId;
  endGame("restart");
  clearSavedGame();
  savedGame = undefined;
  launchRun(target, variationId, randomSeed());
}

/** Ends the shift back to the menu, leaving the saved record exactly as it was. */
function leaveRun(): void {
  if (game && !gameEnded) endGame("user_quit");
  teardownRun();
  closeDialogs();
  screen = "menu";
  savedGame = ownedSavedGame();
  drawMenu();
}

/** A new agent session snaps the overlay back to the menu wherever it was. */
function snapToMenu(): void {
  if (screen === "game") {
    leaveRun();
    return;
