/**
 * Closes the books on a run exactly once: the trace is submitted, the analytics
 * event fired, and a *naturally completed* run — never a quit, restart or
 * shutdown — appends one local score row.
 */
function endGame(reason: EpisodeEndReason): void {
  if (!game || !entry || gameEnded) return;
  gameEnded = true;
  stopTick();
  cancelTraceFlush();
  stopWorkerOrchestrator();

  const completed = reason === "won" || reason === "lost" || reason === "game_over";
  const score = game.score();
  const success = game.hasWon();
  const durationMs = Math.max(0, Date.now() - gameStartedAt);
  const trace = activeTrace;
  if (trace) submitTrace(trace, reason, completed ? score : undefined);
  activeTrace = undefined;

  captureOverlayEvent("game.ended", {
    game_type: entry.id,
    variation_id: runVariationId,
    outcome: completed ? "completed" : "abandoned",
    score,
    success,
    duration_ms: durationMs,
    actions_taken: actionsTaken,
  }, gameSessionId);

  if (!completed) return;
  // A finished shift has nothing left to resume; the menu should not offer it.
  saveRecord = undefined;
  savedGame = undefined;
  clearSavedGame();
  if (!trace) return;
  void invoke("append_local_score", {
    score: {
      game_id: trace.gameId,
      game_type: entry.id,
      variation_id: runVariationId,
      score,
      success,
      completed_at: new Date().toISOString(),
      duration_ms: durationMs,
      platform: "overlay",
    },
  }).then(() => refreshLocalScores()).catch(() => undefined);
}

