    // A record this build can no longer rebuild (older rules, renamed action)
    // is dropped rather than left offering a Resume that does nothing.
    savedGame = undefined;
    clearSavedGame();
    if (screen === "menu") drawMenu();
    return;
  }
  launchRun(target, saved.variationId, saved.seed, { ...restored, saved });
}

/**
 * Restart means "start over with a new run", not "replay this seed": the stored
 * record is thrown away and the fresh run randomizes its own seed (README,
 * "Session save").
 */
function restartRun(): void {
  if (!entry || !game) return;
  const target = entry;
  const variationId = runVariationId;
  endGame("restart");
  clearSavedGame();
  savedGame = undefined;
  launchRun(target, variationId, randomSeed());
}

/** Ends the shift back to the menu, leaving the saved record exactly as it was. */
function leaveRun(): void {
  if (game && !gameEnded) endGame("user_quit");
  teardownRun();
  closeDialogs();
  screen = "menu";
  savedGame = ownedSavedGame();
  drawMenu();
}

/** A new agent session snaps the overlay back to the menu wherever it was. */
function snapToMenu(): void {
  if (screen === "game") {
    leaveRun();
    return;
  }
  closeDialogs();
  screen = "menu";
  savedGame = ownedSavedGame();
  drawMenu();
}

/**
 * Closes the books on a run exactly once: the trace is submitted, the analytics
 * event fired, and a *naturally completed* run — never a quit, restart or
 * shutdown — appends one local score row.
 */
function endGame(reason: EpisodeEndReason): void {
  if (!game || !entry || gameEnded) return;
  gameEnded = true;
  stopTick();
  cancelTraceFlush();
  stopWorkerOrchestrator();

  const completed = reason === "won" || reason === "lost" || reason === "game_over";
  const score = game.score();
  const success = game.hasWon();
  const durationMs = Math.max(0, Date.now() - gameStartedAt);
  const trace = activeTrace;
  if (trace) submitTrace(trace, reason, completed ? score : undefined);
  activeTrace = undefined;

  captureOverlayEvent("game.ended", {
    game_type: entry.id,
    variation_id: runVariationId,
    outcome: completed ? "completed" : "abandoned",
    score,
    success,
    duration_ms: durationMs,
    actions_taken: actionsTaken,
  }, gameSessionId);

  if (!completed) return;
  // A finished shift has nothing left to resume; the menu should not offer it.
  saveRecord = undefined;
  savedGame = undefined;
  clearSavedGame();
  if (!trace) return;
  void invoke("append_local_score", {
    score: {
      game_id: trace.gameId,
      game_type: entry.id,
      variation_id: runVariationId,
      score,
      success,
      completed_at: new Date().toISOString(),
      duration_ms: durationMs,
      platform: "overlay",
    },
  }).then(() => refreshLocalScores()).catch(() => undefined);
}

/**
 * Called after every repaint: the engine, not the shell, decides when a shift
 * is over, and it can end on a tick nobody clicked for.
 */
function settleRun(): void {
  if (!game || replaying || !game.isOver()) return;
  if (!gameEnded) endGame(game.hasWon() ? "won" : "lost");
  showGameEnd();
}

/** The end-of-shift card. Idempotent, so a full repaint puts it back. */
function showGameEnd(): void {
  if (!game || !entry) return;
  const board = screenElement.querySelector<HTMLElement>(".board");
  if (!board || board.querySelector(".game-end-overlay")) return;
  const won = game.hasWon();
  const score = game.score();
  const best = personalBest(entry.id, score);
  const isArena = game.name === "restaurant-arena";
  const overlay = document.createElement("div");
  overlay.className = "game-end-overlay";
  overlay.dataset.tone = won ? "win" : "loss";
  overlay.innerHTML = `<div class="game-end-content${isArena ? " arena-end-content" : ""}">
    <h2 class="game-end-title">${won ? "Shift complete" : "Shift over"}</h2>
    <p class="game-end-stats">Score ${score}${best === undefined ? "" : ` · Personal best ${best}`}</p>
    ${getArenaDebriefHtml()}
    ${getArenaTimelineHtml()}
    ${getArenaEvidenceHtml()}
    ${sessionReceiptHtml()}
    <div class="game-end-actions">
      <button type="button" class="primary" data-end="restart">↻ Play again</button>
      <button type="button" data-end="menu">Menu</button>
      ${isArena ? `<div class="export-trace-group">
        <button type="button" class="export-trace-btn" data-action="export-trace">⤓ Export Trace</button>
        <button type="button" class="export-trace-btn-alt" data-action="export-trace-jsonl">JSONL</button>
      </div>` : ""}
    </div>
  </div>`;
  board.appendChild(overlay);
  overlay.querySelector<HTMLButtonElement>("[data-end=restart]")?.focus();
}

/** A host `gamepigeon:launch` or a preview `?game=` deep link. */
function launchFromRequest(gameId: string | undefined | null, variationId?: string | null): void {
  if (!gameId || screen === "gate") return;
  const target = findGame(gameId);
  if (!target || !isPlayable(target)) return;
  const variation = target.variations.find((item) => item.id === variationId) ?? target.variations[0];
  if (!variation) return;
  launchRun(target, variation.id, randomSeed());
}

