document.querySelector("#account-chip")?.addEventListener("click", () => {
  // Signed in, the chip is the way out — behind a confirmation, because signing
  // out ends the shift as well as the session.
  if (isSignedIn()) setDialog("signout", true);
  else void beginSignIn();
});
// The gate's sign-in button is handled by the screen click delegation above,
// since it isn't in the DOM yet at bind time.

/** The titlebar, the pill, and the three dialogs: all static markup, bound once. */
function bindWindowChrome(): void {
  document.querySelector("#resize")?.addEventListener("click", toggleExpanded);
  document.querySelector("#hide")?.addEventListener("click", minimizeToPill);
  // Ends the helper process for this session; the launcher stops reopening it
  // until the next one starts.
  document.querySelector("#shutdown")?.addEventListener("click", () => {
    if (game && !gameEnded) endGame("client_closed");
    void invoke("shutdown").catch(() => undefined);
  });
  bindPill();

  document.querySelector("#return-code")?.addEventListener("click", () => runDialogCommand("back-to-coding"));
  document.querySelector("#continue-game")?.addEventListener("click", () => runDialogCommand("continue"));
  document.querySelector("#how-to-play-from-pause")?.addEventListener("click", () => runDialogCommand("how-to-play"));
  document.querySelector("#return-menu")?.addEventListener("click", () => runDialogCommand("menu"));
  document.querySelector("#how-to-play-close")?.addEventListener("click", () => setDialog("how-to-play", false));
  document.querySelector("#signout-confirm")?.addEventListener("click", () => void confirmSignOut());
  document.querySelector("#signout-cancel")?.addEventListener("click", () => setDialog("signout", false));

  syncResizeControl();
}

// ── Host events ───────────────────────────────────────────────────────
//
// Everything the native shell and the harness hooks can ask of the webview
// (see `apply_action` in tauri/src/main.rs). The launcher already honours the
// auto-open/auto-pause/reset preferences, so an event that arrives here is one
// the user asked for.

window.addEventListener("gamepigeon:launch", (event) => {
  const detail = (event as CustomEvent<{ game?: string; variation?: string }>).detail;
  launchFromRequest(detail?.game, detail?.variation);
});

window.addEventListener("gamepigeon:pause", () => {
  restoreFromPill();
  requestPause("agent");
});

window.addEventListener("gamepigeon:resume", () => {
  restoreFromPill();
  if (paused) resumePlay();
});

window.addEventListener("gamepigeon:reset", () => snapToMenu());

window.addEventListener("gamepigeon:auth-success", (event) => {
  clearSignInPending();
  const email = (event as CustomEvent<{ email?: string }>).detail?.email;
  void loadAuthSession().then((user) => {
    if (user) {
      enterArcade(user);
      return;
    }
    // Signed in but the session did not land on disk: saves and scores are
    // keyed by account id, so the gate stays rather than guessing one.
    setSignInStatus("error", `Signed in${email ? ` as ${email}` : ""}, but the session could not be read. Try again.`);
  });
});

window.addEventListener("gamepigeon:auth-error", (event) => {
  clearSignInPending();
  const message = (event as CustomEvent<string>).detail;
  setSignInStatus("error", typeof message === "string" && message ? message : "Sign-in failed. Try again.");
});

window.addEventListener("gamepigeon:sync-error", (event) => {
  const message = (event as CustomEvent<string>).detail;
  setSyncError(typeof message === "string" && message ? message : "Gameplay sync is paused.");
});

window.addEventListener("gamepigeon:sync-success", () => setSyncError(null));

/** Past the gate: the arcade, its history, and whatever the last launch left behind. */
function enterArcade(user: AuthUser): void {
  savedGame = ownedSavedGame();
  unlockTui(user);
  void invoke<string | null>("read_sync_error").then(setSyncError).catch(() => undefined);
  refreshLocalScores();
  recoverTraces();
  openRequestedRun();
}

/**
 * A deep link names the run the user asked for, so it wins over the "resume
 * last game" preference; with neither, the menu is where a launch starts.
 */
function openRequestedRun(): void {
  const params = new URLSearchParams(window.location.search);
  const requested = params.get("game");
  if (requested) {
    launchFromRequest(requested, params.get("variation"));
    return;
  }
  if (settings.resumeLastGame && savedGame) resumeSavedGame();
}

bindUpdateBanner();
void refreshUpdateBanner();
bindWindowChrome();

void loadSettings().then(async () => {
  workerModel = await invoke<TraceV3Model | undefined>("read_worker_model_config").catch(() => undefined);
  captureOverlayEvent("app.opened", { app_version: typeof __APP_VERSION__ !== "undefined" ? __APP_VERSION__ : "0.2.0", platform: "overlay" });
  // `loadSettings` has just read the preferred boot size; the frame (and the
  // browser preview, which mirrors it) is put there before anything is drawn.
  syncResizeControl();
  await applyOverlaySize(windowHandle, boardSize()).catch(() => undefined);

  if (!isTauri()) {
    if (new URLSearchParams(window.location.search).get("scores") === "demo") localScores = PREVIEW_SCORES;
    // No accounts in the browser preview: the anonymous player owns the saves.
    savedGame = ownedSavedGame();
    screen = "menu";
    drawMenu();
    refreshLocalScores();
    openRequestedRun();
  } else {
    void loadAuthSession().then((user) => {
      if (user) enterArcade(user);
      else drawGate();
    });
  }
});

