import { describe, expect, test } from "bun:test";
import { pauseCommandForKey, pausePrompt, resumesPlay } from "./pause-state.js";

describe("pause prompt", () => {
  test("names the agent as the reason it took the screen", () => {
    // The Stop hook's pause is the one that needs explaining: the player did
    // not ask for it, so the card says who did.
    expect(pausePrompt({ inRun: true, over: false, source: "agent" })).toEqual({
      show: true,
      title: "Your agent needs you",
    });
    expect(pausePrompt({ inRun: true, over: false, source: "player" })).toEqual({
      show: true,
      title: "Paused",
    });
  });

  test("stays down when there is no unfinished run behind it", () => {
    // Nothing to pause on the menu, and a finished shift already has its own
    // end card — covering it with a Continue button would offer a run back
    // that cannot be continued.
    expect(pausePrompt({ inRun: false, over: false, source: "agent" }).show).toBe(false);
    expect(pausePrompt({ inRun: true, over: true, source: "agent" }).show).toBe(false);
    expect(pausePrompt({ inRun: false, over: true, source: "player" }).show).toBe(false);
  });
});

describe("pause dialog keys", () => {
  test("Enter and Esc both go back to the coding prompt", () => {
    // Enter is the shortcut the Stop hook advertises; Esc is what a player who
    // never wanted the overlay reaches for. They mean the same thing here.
    expect(pauseCommandForKey("Enter")).toBe("back-to-coding");
    expect(pauseCommandForKey("Escape")).toBe("back-to-coding");
  });

  test("maps continue, menu and help to their advertised keys", () => {
    expect(pauseCommandForKey("c")).toBe("continue");
    expect(pauseCommandForKey("C")).toBe("continue");
    expect(pauseCommandForKey(" ")).toBe("continue");
    expect(pauseCommandForKey("m")).toBe("menu");
    expect(pauseCommandForKey("M")).toBe("menu");
    expect(pauseCommandForKey("?")).toBe("how-to-play");
    expect(pauseCommandForKey("h")).toBe("how-to-play");
    expect(pauseCommandForKey("H")).toBe("how-to-play");
  });

  test("ignores keys the dialog does not claim", () => {
    // Anything unclaimed has to fall through untouched: the board underneath
    // must not act on a key pressed at a dialog.
    for (const key of ["ArrowUp", "1", "v", "Tab", "F5"]) {
      expect(pauseCommandForKey(key)).toBeNull();
    }
  });

  test("only continue hands the shift back", () => {
    expect(resumesPlay("continue")).toBe(true);
    for (const command of ["back-to-coding", "menu", "how-to-play"] as const) {
      expect(resumesPlay(command)).toBe(false);
    }
  });
});

