import { describe, expect, test } from "bun:test";
import { REGISTRY, type GameEntry } from "../src/games/registry.js";
import {
  appendSavedAction,
  clearSavedGame,
  loadSavedGame,
  newSavedGame,
  restoreGame,
  saveGame,
  type SavedGame,
} from "./persistence.js";

const STORAGE_KEY = "gamepigeon.arcade.active-game.v1";
const MAX_ACTIONS = 50_000;

function memoryStorage(): Storage {
  const items = new Map<string, string>();
  return {
    get length() {
      return items.size;
    },
    clear: () => items.clear(),
    getItem: (key: string) => items.get(key) ?? null,
    key: (index: number) => [...items.keys()][index] ?? null,
    removeItem: (key: string) => void items.delete(key),
    setItem: (key: string, value: string) => void items.set(key, value),
  } as Storage;
}

/** A store that refuses every write, the way a full or disabled one does. */
function brokenStorage(): Storage {
  return {
    length: 0,
    clear: () => {},
    getItem: () => "{",
    key: () => null,
    removeItem: () => {
      throw new Error("storage disabled");
    },
    setItem: () => {
      throw new Error("quota exceeded");
    },
  } as Storage;
}

const arena: GameEntry = REGISTRY[0]!;

function record(actions: string[] = []): SavedGame {
  const saved = newSavedGame(arena, arena.variations[0]!.id, 4_242, "usr_1");
  for (const action of actions) appendSavedAction(saved, action);
  return saved;
}

describe("the saved run record", () => {
  test("starts from a seed with nothing taken yet", () => {
    const saved = newSavedGame(arena, "training-shift", 7, "usr_1");
    expect(saved).toEqual({
      schemaVersion: 1,
      ownerId: "usr_1",
      gameId: arena.id,
      // The rules version is stored so a later build can tell whether its
      // engine still understands this log.
      gameVersion: arena.version,
      variationId: "training-shift",
      seed: 7,
      actions: [],
    });
  });

  test("round-trips through storage", () => {
    const storage = memoryStorage();
    const saved = record(["sim_start", "tick", "tick"]);
    saveGame(saved, storage);
    expect(loadSavedGame(storage)).toEqual(saved);
  });

  test("keeps exactly one run, overwriting the last", () => {
    const storage = memoryStorage();
    saveGame(record(["sim_start"]), storage);
    saveGame(record(["sim_start", "tick"]), storage);
    expect(storage.length).toBe(1);
    expect(loadSavedGame(storage)?.actions).toEqual(["sim_start", "tick"]);
  });

  test("clearing throws the remembered run away", () => {
    const storage = memoryStorage();
    saveGame(record(["sim_start"]), storage);
    clearSavedGame(storage);
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("never lets a broken store interrupt the run being played", () => {
    const storage = brokenStorage();
    expect(() => saveGame(record(["sim_start"]), storage)).not.toThrow();
    expect(() => clearSavedGame(storage)).not.toThrow();
    // Unparseable contents read as "nothing saved", not as a crash on boot.
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("rejects records this build cannot trust", () => {
    const storage = memoryStorage();
    const valid = record(["sim_start"]);
    const cases: unknown[] = [
      { ...valid, schemaVersion: 2 },
      { ...valid, seed: 1.5 },
      { ...valid, ownerId: 7 },
      { ...valid, actions: "sim_start" },
      { ...valid, actions: ["sim_start", 3] },
      { ...valid, gameVersion: undefined },
      "not an object",
    ];
    for (const broken of cases) {
      storage.setItem(STORAGE_KEY, JSON.stringify(broken));
      expect(loadSavedGame(storage)).toBeNull();
    }
  });

  test("stops growing rather than becoming unloadable", () => {
    // Past the cap `loadSavedGame` would reject the whole record, so the tail is
    // dropped to keep a resumable prefix on disk.
    const storage = memoryStorage();
    const saved = record();
    for (let index = 0; index < MAX_ACTIONS; index++) {
      expect(appendSavedAction(saved, "tick")).toBe(true);
    }
    expect(appendSavedAction(saved, "tick")).toBe(false);
    expect(saved.actions.length).toBe(MAX_ACTIONS);
    saveGame(saved, storage);
    expect(loadSavedGame(storage)?.actions.length).toBe(MAX_ACTIONS);
  });
});

describe("rebuilding a saved run", () => {
  test("replays the log into the state the player left", () => {
    const actions = ["sim_start", "tick", "tick", "hold_seating"];
    const saved = record(actions);

    const restored = restoreGame(arena, saved);
    expect(restored).not.toBeNull();

    const expected = arena.create!(saved.variationId);
    expected.reset(saved.seed);
    for (const action of actions) expected.step(action);
    expect(restored!.game.state()).toEqual(expected.state());
    expect(restored!.game.score()).toBe(expected.score());
    // Only the accepted actions are reported back, since that count is what the
    // shell resumes its own action tally from.
    expect(restored!.actions).toEqual(actions);
  });

  test("refuses a record from another game or another rules version", () => {
    expect(restoreGame(arena, { ...record(), gameId: "some-other-game" })).toBeNull();
    expect(restoreGame(arena, { ...record(), gameVersion: "0" })).toBeNull();
  });

  test("refuses a log holding an action this build no longer accepts", () => {
    // A renamed or retired action means the rest of the log lands on a
    // different floor than it was recorded against; nothing after it is safe.
    expect(restoreGame(arena, record(["sim_start", "retired_action"]))).toBeNull();
  });

  test("refuses a game that cannot be built at all", () => {
    const comingSoon: GameEntry = { ...arena, create: null };
    expect(restoreGame(comingSoon, record())).toBeNull();
  });
});

