import { Window } from "happy-dom";
import { readFileSync } from "node:fs";

const html = readFileSync("/app/overlay/dist/index.html", "utf8");
const w = new Window({ url: "http://localhost/index.html", width: 600, height: 850 });
w.document.write(html);

const g = globalThis as any;
for (const key of ["window", "document", "navigator", "location", "HTMLElement", "HTMLInputElement", "HTMLSelectElement", "HTMLButtonElement", "HTMLTextAreaElement", "HTMLOListElement", "CustomEvent", "Event", "KeyboardEvent", "PointerEvent", "MouseEvent", "Node", "Blob", "URL", "requestAnimationFrame", "cancelAnimationFrame", "getComputedStyle", "ResizeObserver", "localStorage", "performance"]) {
