w.document.write(html);

const g = globalThis as any;
const force = new Set(["navigator", "location", "localStorage", "sessionStorage", "requestAnimationFrame", "cancelAnimationFrame", "getComputedStyle", "performance", "screen", "customElements", "matchMedia"]);
for (const key of Reflect.ownKeys(w) as string[]) {
  if (typeof key !== "string") continue;
  if (!force.has(key) && key in g) continue;
