import { Window } from "happy-dom";
import { readFileSync } from "node:fs";

const html = readFileSync("/app/overlay/dist/index.html", "utf8");
const w = new Window({ url: "http://localhost/index.html", width: 600, height: 850 });
w.document.write(html);

const g = globalThis as any;
const force = new Set(["navigator", "location", "localStorage", "sessionStorage", "requestAnimationFrame", "cancelAnimationFrame", "getComputedStyle", "performance", "screen", "customElements", "matchMedia"]);
for (const key of Reflect.ownKeys(w) as string[]) {
  if (typeof key !== "string") continue;
  if (!force.has(key) && key in g) continue;
  const value = (w as any)[key];
  if (value === undefined) continue;
  try { g[key] = value; } catch { /* read-only global */ }
}
g.window = w;
g.self = w;
g.document = w.document;

// Phaser probes a 2D canvas at import time and boots a WebGL renderer on
// mount. happy-dom has neither, so the probe gets a stub and the mount (which
// app.ts defers to requestAnimationFrame) never runs — this smoke run is about
// the DOM shell around the canvas, not the canvas.
const stubContext: unknown = new Proxy({}, {
  get(_target, prop) {
    if (prop === "canvas") return w.document.createElement("canvas");
    if (prop === "getImageData" || prop === "createImageData") {
      return () => ({ data: new Uint8ClampedArray(64), width: 4, height: 4 });
    }
    if (prop === "measureText") return () => ({ width: 8 });
    return () => undefined;
  },
  set: () => true,
});
(g.HTMLCanvasElement as any).prototype.getContext = () => stubContext;
(g.HTMLCanvasElement as any).prototype.toDataURL = () => "data:image/png;base64,";
g.requestAnimationFrame = () => 0;
g.cancelAnimationFrame = () => {};
w.requestAnimationFrame = g.requestAnimationFrame;
// Phaser needs a canvas; happy-dom has none that boots WebGL, so keep the
// scene from mounting by making rAF a no-op after the smoke checks start.
await import("/app/overlay/app.ts");
await new Promise((r) => setTimeout(r, 400));

const doc = w.document as any;
const screenEl = doc.querySelector("#screen");
const log = (...args: unknown[]) => console.log(...args);
log("screen:", screenEl.dataset.screen);

// menu -> variations -> launch
doc.querySelector("[data-game-index='0']").click();
log("after game card:", screenEl.dataset.screen);
doc.querySelector("[data-variation-index='0']").click();
log("after variation:", screenEl.dataset.screen, "game:", screenEl.dataset.game);
log("saved record:", (w.localStorage.getItem("gamepigeon.arcade.active-game.v1") ?? "").slice(0, 120));

// hide -> pill
doc.querySelector("#hide").click();
log("mode:", doc.body.dataset.mode, "pause dialog hidden:", doc.querySelector("#return-prompt").hidden);
doc.querySelector("#pill").click();
log("after pill click, mode:", doc.body.dataset.mode);
log("pause dialog hidden:", doc.querySelector("#return-prompt").hidden, "title:", doc.querySelector("#return-title").textContent);
doc.querySelector("#continue-game").click();
log("after continue, dialog hidden:", doc.querySelector("#return-prompt").hidden);

// resize toggle
doc.querySelector("#resize").click();
