// how to play from the pause dialog
w.dispatchEvent(new w.Event("gamepigeon:pause"));
log("agent pause title:", doc.querySelector("#return-title").textContent, "hidden:", doc.querySelector("#return-prompt").hidden);
doc.querySelector("#how-to-play-from-pause").click();
