w.dispatchEvent(new w.Event("gamepigeon:resume"));
log("after host resume, pause hidden:", doc.querySelector("#return-prompt").hidden);

// restart mid-run: new seed, empty log
const before = JSON.parse(w.localStorage.getItem("gamepigeon.arcade.active-game.v1")!);
w.document.dispatchEvent;
const kd = (key: string) => doc.body.dispatchEvent(new w.KeyboardEvent("keydown", { key, bubbles: true }));
kd("r");
const after = JSON.parse(w.localStorage.getItem("gamepigeon.arcade.active-game.v1")!);
log("restart reseeded:", before.seed !== after.seed, "actions:", after.actions.length, "screen:", screenEl.dataset.screen);

// back to the menu keeps the record; resume rebuilds it
kd("Escape");
log("escape from run -> mode:", doc.body.dataset.mode);
doc.querySelector("#pill").click();
doc.querySelector("#return-menu").click();
log("after menu:", screenEl.dataset.screen, "resume button:", Boolean(doc.querySelector("[data-resume]")));
log("record kept:", Boolean(w.localStorage.getItem("gamepigeon.arcade.active-game.v1")));
doc.querySelector("[data-resume]").click();
log("after resume:", screenEl.dataset.screen, "game:", screenEl.dataset.game);

