const started = JSON.parse(w.localStorage.getItem("gamepigeon.arcade.active-game.v1")!);
log("after space+wait, logged actions:", started.actions.slice(0, 4), "count:", started.actions.length);

for (let i = 0; i < 1200 && !doc.querySelector(".game-end-overlay"); i++) kd("t");
