log("end card:", Boolean(card), "tone:", card?.dataset.tone);
log("end title:", card?.querySelector(".game-end-title")?.textContent, "|", card?.querySelector(".game-end-stats")?.textContent);
log("end buttons:", [...card?.querySelectorAll("button") ?? []].map((b: any) => b.dataset.end ?? b.dataset.action).join(","));
log("session receipt on card:", Boolean(card?.querySelector("[data-session-id]")));
log("finished run cleared the save:", w.localStorage.getItem("gamepigeon.arcade.active-game.v1"));
card?.querySelector("[data-end=menu]")?.click();
log("after end-card menu:", screenEl.dataset.screen, "resume offered:", Boolean(doc.querySelector("[data-resume]")));

import { describe, expect, test } from "bun:test";
import { REGISTRY, type GameEntry } from "../src/games/registry.js";
import {
  appendSavedAction,
  clearSavedGame,
  loadSavedGame,
  newSavedGame,
  restoreGame,
  saveGame,
  type SavedGame,
} from "./persistence.js";

const STORAGE_KEY = "gamepigeon.arcade.active-game.v1";
const MAX_ACTIONS = 50_000;

function memoryStorage(): Storage {
  const items = new Map<string, string>();
  return {
    get length() {
      return items.size;
    },
    clear: () => items.clear(),
    getItem: (key: string) => items.get(key) ?? null,
    key: (index: number) => [...items.keys()][index] ?? null,
    removeItem: (key: string) => void items.delete(key),
    setItem: (key: string, value: string) => void items.set(key, value),
  } as Storage;
}

/** A store that refuses every write, the way a full or disabled one does. */
function brokenStorage(): Storage {
  return {
    length: 0,
    clear: () => {},
    getItem: () => "{",
    key: () => null,
    removeItem: () => {
      throw new Error("storage disabled");
    },
    setItem: () => {
      throw new Error("quota exceeded");
    },
  } as Storage;
}

const arena: GameEntry = REGISTRY[0]!;

function record(actions: string[] = []): SavedGame {
  const saved = newSavedGame(arena, arena.variations[0]!.id, 4_242, "usr_1");
  for (const action of actions) appendSavedAction(saved, action);
  return saved;
}

describe("the saved run record", () => {
  test("starts from a seed with nothing taken yet", () => {
    const saved = newSavedGame(arena, "training-shift", 7, "usr_1");
    expect(saved).toEqual({
      schemaVersion: 1,
      ownerId: "usr_1",
      gameId: arena.id,
      // The rules version is stored so a later build can tell whether its
      // engine still understands this log.
      gameVersion: arena.version,
      variationId: "training-shift",
      seed: 7,
      actions: [],
    });
  });

  test("round-trips through storage", () => {
    const storage = memoryStorage();
    const saved = record(["sim_start", "tick", "tick"]);
    saveGame(saved, storage);
    expect(loadSavedGame(storage)).toEqual(saved);
  });

  test("keeps exactly one run, overwriting the last", () => {
    const storage = memoryStorage();
    saveGame(record(["sim_start"]), storage);
    saveGame(record(["sim_start", "tick"]), storage);
    expect(storage.length).toBe(1);
    expect(loadSavedGame(storage)?.actions).toEqual(["sim_start", "tick"]);
  });

  test("clearing throws the remembered run away", () => {
    const storage = memoryStorage();
    saveGame(record(["sim_start"]), storage);
    clearSavedGame(storage);
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("never lets a broken store interrupt the run being played", () => {
    const storage = brokenStorage();
    expect(() => saveGame(record(["sim_start"]), storage)).not.toThrow();
    expect(() => clearSavedGame(storage)).not.toThrow();
    // Unparseable contents read as "nothing saved", not as a crash on boot.
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("rejects records this build cannot trust", () => {
    const storage = memoryStorage();
    const valid = record(["sim_start"]);
    const cases: unknown[] = [
      { ...valid, schemaVersion: 2 },
      { ...valid, seed: 1.5 },
      { ...valid, ownerId: 7 },
      { ...valid, actions: "sim_start" },
      { ...valid, actions: ["sim_start", 3] },
      { ...valid, gameVersion: undefined },
      "not an object",
    ];
    for (const broken of cases) {
      storage.setItem(STORAGE_KEY, JSON.stringify(broken));
      expect(loadSavedGame(storage)).toBeNull();
    }
  });

  test("stops growing rather than becoming unloadable", () => {
    // Past the cap `loadSavedGame` would reject the whole record, so the tail is
    // dropped to keep a resumable prefix on disk.
    const storage = memoryStorage();
    const saved = record();
    let accepted = 0;
    while (appendSavedAction(saved, "tick")) accepted++;
    expect(accepted).toBe(MAX_ACTIONS);
    expect(appendSavedAction(saved, "tick")).toBe(false);
    expect(saved.actions.length).toBe(MAX_ACTIONS);
    saveGame(saved, storage);
    expect(loadSavedGame(storage)?.actions.length).toBe(MAX_ACTIONS);
  });
});

describe("rebuilding a saved run", () => {
  test("replays the log into the state the player left", () => {
    const actions = ["sim_start", "tick", "tick", "hold_seating"];
    const saved = record(actions);

    const restored = restoreGame(arena, saved);
    expect(restored).not.toBeNull();

    const expected = arena.create!(saved.variationId);
    expected.reset(saved.seed);
    for (const action of actions) expected.step(action);
    expect(restored!.game.state()).toEqual(expected.state());
    expect(restored!.game.score()).toBe(expected.score());
    // Only the accepted actions are reported back, since that count is what the
    // shell resumes its own action tally from.
    expect(restored!.actions).toEqual(actions);
  });

  test("refuses a record from another game or another rules version", () => {
    expect(restoreGame(arena, { ...record(), gameId: "some-other-game" })).toBeNull();
    expect(restoreGame(arena, { ...record(), gameVersion: "0" })).toBeNull();
  });

  test("refuses a log holding an action this build no longer accepts", () => {
    // A renamed or retired action means the rest of the log lands on a
    // different floor than it was recorded against; nothing after it is safe.
    expect(restoreGame(arena, record(["sim_start", "retired_action"]))).toBeNull();
  });

  test("refuses a game that cannot be built at all", () => {
    const comingSoon: GameEntry = { ...arena, create: null };
    expect(restoreGame(comingSoon, record())).toBeNull();
  });
});

import { describe, expect, test } from "bun:test";
import {
  COMPACT_SIZE,
  EXPANDED_SIZE,
  MIN_SIZE,
  PILL_SIZE,
  applyOverlaySize,
  type OverlaySize,
  type OverlayWindow,
} from "./tauri-bridge.js";

type SizeCall = { call: "size" | "min"; width: number; height: number };

function recordingWindow(): { window: OverlayWindow; calls: SizeCall[] } {
  const calls: SizeCall[] = [];
  const record = (call: "size" | "min") => async (size?: unknown) => {
    const { width, height } = size as OverlaySize;
    calls.push({ call, width, height });
  };
  const window: OverlayWindow = {
    hide: async () => {},
    setSize: record("size"),
    setMinSize: record("min"),
    center: async () => {},
    startDragging: async () => {},
  };
  return { window, calls };
}

describe("overlay window sizes", () => {
  test("are the exact sizes the README documents", () => {
    // The native frame and overlay/preview.html both read these, so the browser
    // preview only mirrors the app while the numbers stay in one place.
    expect(COMPACT_SIZE).toEqual({ width: 600, height: 850 });
    expect(EXPANDED_SIZE).toEqual({ width: 830, height: 900 });
    expect(PILL_SIZE).toEqual({ width: 144, height: 48 });
    expect(MIN_SIZE).toEqual({ width: 500, height: 700 });
  });

  test("the pill is smaller than the floor it collapses from", () => {
    // The whole reason applyOverlaySize has two orderings.
    expect(PILL_SIZE.width).toBeLessThan(MIN_SIZE.width);
    expect(PILL_SIZE.height).toBeLessThan(MIN_SIZE.height);
  });
});

describe("applyOverlaySize", () => {
  test("lowers the minimum before shrinking to the pill", async () => {
    const { window, calls } = recordingWindow();
    await applyOverlaySize(window, PILL_SIZE);
    // A minimum above the requested size silently clamps setSize, so 144×48
    // only lands if the floor drops out of the way first.
    expect(calls).toEqual([
      { call: "min", width: 144, height: 48 },
      { call: "size", width: 144, height: 48 },
    ]);
  });

  test("raises the minimum only once the window can hold it", async () => {
    const { window, calls } = recordingWindow();
    await applyOverlaySize(window, COMPACT_SIZE);
    expect(calls).toEqual([
      { call: "size", width: 600, height: 850 },
      { call: "min", width: 500, height: 700 },
    ]);
  });

  test("restores the documented floor when coming back from the pill", async () => {
    const { window, calls } = recordingWindow();
    await applyOverlaySize(window, PILL_SIZE);
    await applyOverlaySize(window, COMPACT_SIZE);
    // The pill's own minimum must not survive the trip back: the restored
    // window is never allowed below 500×700.
    expect(calls.at(-1)).toEqual({ call: "min", width: 500, height: 700 });
  });

  test("treats a one-axis shrink as a shrink", async () => {
    const { window, calls } = recordingWindow();
    // 600 clears the 500 floor; 600 does not clear the 700 one. Ordering by
    // width alone would clamp this resize to 600×700.
    await applyOverlaySize(window, { width: 600, height: 600 });
    expect(calls[0]).toEqual({ call: "min", width: 600, height: 600 });
    expect(calls[1]).toEqual({ call: "size", width: 600, height: 600 });
  });
});

import { describe, expect, test } from "bun:test";
import { pauseCommandForKey, pausePrompt, resumesPlay } from "./pause-state.js";

describe("pause prompt", () => {
  test("names the agent as the reason it took the screen", () => {
    // The Stop hook's pause is the one that needs explaining: the player did
    // not ask for it, so the card says who did.
    expect(pausePrompt({ inRun: true, over: false, source: "agent" })).toEqual({
      show: true,
      title: "Your agent needs you",
    });
    expect(pausePrompt({ inRun: true, over: false, source: "player" })).toEqual({
      show: true,
      title: "Paused",
    });
  });

  test("stays down when there is no unfinished run behind it", () => {
    // Nothing to pause on the menu, and a finished shift already has its own
    // end card — covering it with a Continue button would offer a run back
    // that cannot be continued.
    expect(pausePrompt({ inRun: false, over: false, source: "agent" }).show).toBe(false);
    expect(pausePrompt({ inRun: true, over: true, source: "agent" }).show).toBe(false);
    expect(pausePrompt({ inRun: false, over: true, source: "player" }).show).toBe(false);
  });
});

describe("pause dialog keys", () => {
  test("Enter and Esc both go back to the coding prompt", () => {
    // Enter is the shortcut the Stop hook advertises; Esc is what a player who
    // never wanted the overlay reaches for. They mean the same thing here.
    expect(pauseCommandForKey("Enter")).toBe("back-to-coding");
    expect(pauseCommandForKey("Escape")).toBe("back-to-coding");
  });

  test("maps continue, menu and help to their advertised keys", () => {
    expect(pauseCommandForKey("c")).toBe("continue");
    expect(pauseCommandForKey("C")).toBe("continue");
    expect(pauseCommandForKey(" ")).toBe("continue");
    expect(pauseCommandForKey("m")).toBe("menu");
    expect(pauseCommandForKey("M")).toBe("menu");
    expect(pauseCommandForKey("?")).toBe("how-to-play");
    expect(pauseCommandForKey("h")).toBe("how-to-play");
    expect(pauseCommandForKey("H")).toBe("how-to-play");
  });

  test("ignores keys the dialog does not claim", () => {
    // Anything unclaimed has to fall through untouched: the board underneath
    // must not act on a key pressed at a dialog.
    for (const key of ["ArrowUp", "1", "v", "Tab", "F5"]) {
      expect(pauseCommandForKey(key)).toBeNull();
    }
  });

  test("only continue hands the shift back", () => {
    expect(resumesPlay("continue")).toBe(true);
    for (const command of ["back-to-coding", "menu", "how-to-play"] as const) {
      expect(resumesPlay(command)).toBe(false);
    }
  });
});

