const kd = (key: string) => doc.body.dispatchEvent(new w.KeyboardEvent("keydown", { key, bubbles: true }));
const ticks = () => JSON.parse(w.localStorage.getItem("gamepigeon.arcade.active-game.v1")!).actions.filter((a: string) => a === "tick").length;

doc.querySelector("[data-game-index='0']").click();
doc.querySelector("[data-variation-index='0']").click();
