w.dispatchEvent(new w.Event("gamepigeon:pause"));
await new Promise((r) => setTimeout(r, 6_000));
log("ticks while paused:", ticks(), "(dialog up:", !doc.querySelector("#return-prompt").hidden, ")");

doc.querySelector("#continue-game").click();
log("dialog after continue:", doc.querySelector("#return-prompt").hidden);
await new Promise((r) => setTimeout(r, 6_000));
log("ticks 6s after continuing:", ticks());
await new Promise((r) => setTimeout(r, 6_000));
log("ticks 12s after continuing:", ticks(), "(engine holds the clock on an open decision)");
EOF
